 $('movement-note').textContent='Blue: period totals. Green/red: signed change. Grey: unmatched or unavailable detail, never assumed to be zero. Contributions reconcile to the total difference. Large lists group the remaining matched changes into Other.';
 $('movement-table').innerHTML=table(['Product / group',String(ui.bridgeYear),String(d.snapshot.year),'Change','PPG%'],result.items.map(r=>[e(r.name),n(r.previous),n(r.current),n(r.delta),pct(r.ppg)]));
